// Dexmedetomidine infusion calculator. Every number comes from the Dexdor
// SmPC (emc, rev. Jul 2022): ICU 0.2-1.4 mcg/kg/h without loading; procedural
// loading 1 (or 0.5) mcg/kg over 10 min, then 0.2-1 mcg/kg/h; 4 or 8 mcg/mL.
function dexRates(w, mode, load, loadDose, rate, conc) {
  const lim = mode === "icu" ? { lo: 0.2, hi: 1.4 } : { lo: 0.2, hi: 1.0 };
  const out = { lim };
  if (!(w > 0) || !(conc > 0)) return out;
  if (load && mode === "proc") {
    out.loadMcg = loadDose * w;
    out.loadMl = out.loadMcg / conc;
    out.loadMlh = out.loadMl * 6; // delivered over 10 min
  }
  if (rate > 0) {
    out.mcgh = rate * w;
    out.mlh = out.mcgh / conc;
    out.hours50 = out.mlh > 0 ? 50 / out.mlh : null;
  }
  return out;
}
